'use strict';

const expect = require('chai').expect;
const sinon = require('sinon');
const MSSQL_Client = require('../../../lib/dialects/mssql');
const client = new MSSQL_Client({ client: 'mssql' });

describe('MSSQL SchemaBuilder', function () {
  let tableSql;
